typedef unsigned int u_int;

class vector3d
{
public:
	float x, y, z;
};

template <int n> struct SplineCoeffs
{
	float a[n], b[n], c[n], d[n];
};

typedef struct
{
	SplineCoeffs<16> y, z;
} WaveProfileCoeffs;

struct WavePositionHint
{
	float x, z;
	float xprofile;
	u_int xcell, zcell;
	u_int xgrid, zgrid;
	WaveProfileCoeffs wpc;
};

struct nglTexture;

class game
{
public:
	int get_num_players();
};

extern game *g_game_ptr;
extern nglTexture *fx_tex[11];

enum
{
	LIP_SNAP_LEFT,
	LIP_SNAP_RIGHT,
	LIP_LAUNCH
};

typedef struct
{
	vector3d position;
	vector3d normal;
	WavePositionHint hint;
	float age;
	bool valid;
	int hero_index;
	nglTexture *texture;
	int type;
} lip_splash_t;

#define MAX_LIP_SPLASHES 2
extern lip_splash_t lip_splashes[MAX_LIP_SPLASHES];

enum
{
	FX_TEX_CRASH,
	FX_TEX_CRASH2,
	FX_TEX_BSPRAY_P,
	FX_TEX_BSPRAY_G,
	FX_TEX_TRAIL,
	FX_TEX_PADDLE,
	FX_TEX_FLOATER,
	FX_TEX_WEATHER,
	FX_TEX_ALGEE,
	FX_TEX_SNAP_SPRAY,
	FX_TEX_LAUNCH
};

void ks_fx_create_launch_splash (const vector3d& pos, const vector3d& normal, WavePositionHint& hint, int hero_index)
{
	if (hero_index >= g_game_ptr->get_num_players())
		return;	// no splash for AI surfers, because ks_fx_draw isn't called for them.

	lip_splash_t *splash = NULL;

	for (int i = 0; i < MAX_LIP_SPLASHES; i++)
	{
		if (!lip_splashes[i].valid)
		{
			splash = &lip_splashes[i];
			break;
		}
	}

	if (splash != NULL)
	{
		splash->age = 0;
		splash->valid = true;
		splash->position = pos;
		splash->hint = hint;
		splash->normal = normal;
		splash->type = LIP_LAUNCH;
		splash->hero_index = hero_index;
		splash->texture = fx_tex[FX_TEX_LAUNCH];
	}
}
